<?php
require_once __DIR__.'/includes/bootstrap.php'; require_once __DIR__.'/includes/vsart.php';
if(current_user()){header('Location: dashboard.php');exit;}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$username=trim($_POST['username']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';$confirm=$_POST['confirm']??'';
if(!preg_match('/^[a-zA-Z0-9_]{3,24}$/',$username))$error='Username 3–24 karakter; gunakan huruf, angka, atau underscore.';
elseif(!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Format email tidak valid.';
elseif(strlen($password)<8)$error='Password minimal 8 karakter.';
elseif($password!==$confirm)$error='Konfirmasi password tidak cocok.';
else{try{$pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO users(username,email,password_hash,role,status) VALUES(?,?,?,'player','active')");$q->execute([$username,$email,password_hash($password,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO player_profiles(user_id,display_name) VALUES(?,?)')->execute([$id,$username]);$pdo->prepare('INSERT INTO player_statistics(user_id) VALUES(?)')->execute([$id]);$pdo->commit();session_regenerate_id(true);$_SESSION['user']=['id'=>$id,'username'=>$username,'email'=>$email,'role'=>'player'];header('Location: dashboard.php');exit;}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getCode()==='23000'?'Username atau email sudah digunakan.':'Registrasi gagal. Periksa database lalu coba lagi.';}}}
$pageTitle='Create Account';include __DIR__.'/includes/header.php'; ?>
